rule "Remote Desktop Logon Messages"

when
    has_field("gim_event_type")
    AND to_string($message.event_outcome) == "success"
    AND contains(to_string($message.gim_event_type), "logon")
    AND NOT contains(to_string($message.gim_event_type), "special logon")

then
    let rdp_user = lookup_add_string_list(
        lookup_table: "remote-desktop-session-monitoring",
        key: to_string($message.user_session_id),
        value: [to_string($message.timestamp)]
    );


    let rdp_user = lookup_add_string_list(
        lookup_table: "remote-desktop-session-monitoring",
        key: to_string($message.user_session_id),
        value: [to_string($message.source_hostname)]
    );

    let rdp_user = lookup_add_string_list(
        lookup_table: "remote-desktop-session-monitoring",
        key: to_string($message.user_session_id),
        value: [to_string($message.destination_hostname)]
    );

    let rdp_user = lookup_add_string_list(
        lookup_table: "remote-desktop-session-monitoring",
        key: to_string($message.user_session_id),
        value: [to_string($message.source_ip)]
    );

    let rdp_user = lookup_add_string_list(
        lookup_table: "remote-desktop-session-monitoring",
        key: to_string($message.user_session_id),
        value: [to_string($message.destination_ip)]
    );

    let rdp_user = lookup_add_string_list(
        lookup_table: "remote-desktop-session-monitoring",
        key: to_string("active_rdp_sessions"),
        value: [to_string($message.user_session_id)]
    );

end

rule "Remote Desktop Logon Messages - Replace source_hostname"

when
    has_field("gim_event_type")
    AND has_field("source_ip")
    AND to_string($message.event_outcome) == "success"
    AND (contains(to_string($message.gim_event_type), "logon")
    AND NOT contains(to_string($message.gim_event_type), "special logon")
    OR (contains(to_string($message.gim_event_type), "session disconnect") 
    OR contains(to_string($message.gim_event_type), "session reconnect")))

then
    let source_hostname = lookup_value(
        lookup_table: "remote-desktop-session-monitoring-reverse-dns", 
        key: to_string($message.source_ip)
        );

    let source_hostname = regex_replace(
        pattern: "(.*?)\\.$", 
        value: to_string(source_hostname),
        replacement: "$1"
        );

    set_field("source_hostname", to_string(source_hostname));

end

rule "Remote Desktop Logoff Messages"

when    
    has_field("gim_event_type")
    AND to_string($message.event_outcome) == "success"
    AND contains(to_string($message.gim_event_type), "logoff")
    AND lookup_has_value("remote-desktop-session-monitoring", to_string($message.user_session_id))

then
    // Calculate session duration data
    let session_login_time = list_get(lookup_string_list(
        lookup_table: "remote-desktop-session-monitoring",
        key: to_string($message.user_session_id)
    ),0);

    let login_time = to_long(parse_date(
        value: to_string(session_login_time),
        pattern: "yyyy-MM-dd'T'HH:mm:ss.SSSZ",
        locale: "de_DE").millis);

    let current_time = to_long(parse_date(
        value: to_string($message.timestamp),
        pattern: "yyyy-MM-dd'T'HH:mm:ss.SSSZ",
        locale: "de_DE").millis);

    let user_session_duration = current_time - login_time;

    // Enrich logoff message with session duration data
    set_field("user_session_duration_milliseconds", to_long(user_session_duration));
    set_field("user_session_duration_seconds", to_long(user_session_duration/1000));
    set_field("user_session_duration_minutes", to_long(user_session_duration/1000/60));
    set_field("user_session_duration_hours", to_long(user_session_duration/1000/60/60)); 
    set_field("user_session_duration", string_array_add([], [to_long(user_session_duration), to_long(user_session_duration/1000), to_long(user_session_duration/1000/60), to_long(user_session_duration/1000/60/60)], false));


    // Flag logoff message as windows_rdp related
    set_field("application_name", "windows_rdp");

    // Enrich logoff message with information from Database
    set_field("source_hostname", list_get(lookup_string_list("remote-desktop-session-monitoring", to_string($message.user_session_id)),1));
    set_field("destination_hostname", list_get(lookup_string_list("remote-desktop-session-monitoring", to_string($message.user_session_id)),2));
    set_field("source_ip", list_get(lookup_string_list("remote-desktop-session-monitoring", to_string($message.user_session_id)),3));
    set_field("destination_ip", list_get(lookup_string_list("remote-desktop-session-monitoring", to_string($message.user_session_id)),4));

    // Cleanup login session data from Database (Lookup Table)
    let rdp_user = lookup_clear_key(
        lookup_table: "remote-desktop-session-monitoring",
        key: to_string($message.user_session_id)
    );

    // Cleanup session data from Database (Lookup Table)
    let rdp_user_collection = lookup_remove_string_list(
        lookup_table: "remote-desktop-session-monitoring",
        key: "active_rdp_sessions", 
        value: [to_string($message.user_session_id)]
    );

    // Cleanup session data from Database (Lookup Table)
    let rdp_user_collection = lookup_remove_string_list(
        lookup_table: "remote-desktop-session-monitoring",
        key: "inactive_rdp_sessions", 
        value: [to_string($message.user_session_id)]
    );


end
